    for i in range(1, n):
        for j in range(i, n):
            if is_good_subarray(nums[i:j+1]):
                if i == 0:
                    good_subarrays += (j - i + 1) * pow(2, j-i, MOD - 1)
                else:
                    good_subarrays += lcm(j-i+1, prefix_sums[i-1], MOD - 1)
                    good_subarrays %= MOD
            else:
