def rename_variables(n, variables, target):
    from collections import Counter

    initial_counter = Counter(variables)
    target_counter = Counter(target)
    common_pairs = common(initial_counter.items(), target_counter.items())

    if len(common_pairs) > 2:
        return "NO"

    s, t = common_pairs[0]
    return "YES\n{} {}\n".format(s, t)

def common(a, b):
    c = Counter()
    min_length = min(len(a), len(b))
    for i in range(min_length):
        if a[i] == b[i]:
            c[a[i]] += 1
        else:
            break
    return list(c)

