def bfs(nfa, source, target):
    queue = [(source, source)]
    seen = {source}
    while queue:
        node, seen_node = queue.pop(0)
        if seen_node == target:
            return seen_node
        for next_node in nfa[seen_node]:
            if next_node not in seen:
                seen.add(next_node)
                queue.append((node, seen_node))
    return -1

def find_minimum_lexicographical(nfa):
    seen = set()
    while True:
        prev = -1
        for node in sorted(seen):
            converted = bfs(nfa, node, node)
            if converted != -1 and (prev == -1 or found == -1 or converted < prev) and node < found:
