    B_count = 1 if is_palindrome(B) else 0
    for i in range(1, len(A)):
        if is_palindrome(A[:i]):
            A_count += 1
    for j in range(1, len(B)):
        if is_palindrome(B[:j]):
            B_count += 1

    result = A_count * B_count
    result += (len(A) - A_count) * (len(B) - B_count) * 2
