def count_awesome_substrings(binary_string):
    """
    Counts the number of awesome substrings in a given binary string.
    """
    awesome_count = 0

    # Count the transitions from 0 to 1 and from 1 to 0
    transition_count = binary_string.count('1') - binary_string.count('1', 1)
    transition_count = max(0, transition_count)

    # If the string length is odd, we need at least one 1 to make it even
    if len(binary_string) % 2 != 0:
        transition_count = max(0, transition_count // 2 + 1)

    # Count the substrings ending with 1 and starting with 1
    for i in range(len(binary_string)):
        if binary_string[i] == '1':
            for j in range(i + 1, len(binary_string)):
                if b1sequence(binary_string[i:j+1]):
                    awesome_count += 1

    return awesome_count

def b1sequence(sub):
    """
    Checks if a given string is a valid b1sequence.
    """
    counts = {0: 0, 1: 0}
    for bit in sub:
        counts[1 - counts.get(int(bit), 0)] += 1
    return 1 in counts and (2 * (counts[1] - 1)) > len(sub)

