import sys

def maximize_product_of_components(n, edges):
    vertex_index = {i: i for i in range(1, n + 1)}
    tree = [[] for _ in range(n + 1)]

    for u, v in edges:
        tree[vertex_index[u]].append((vertex_index[v], 1))
        tree[vertex_index[v]].append((vertex_index[u], 1))

    def dfs(node, parent):
        size = 1
        for child, weight in tree[node]:
            if child == parent:
                continue
            size += dfs(child, node)
        return size * weight

    components = {}
    for node in range(1, n + 1):
        if (root := dfs(node, -1)) not in components:
            components[root] = []
        components[root].append((node, dfs(node, -1)))

    max_product = 0
    for components_size, nodes in components.values():
        max_product = max(max_product, components_size + nodes[0] * nodes[1])

    return max_product

