def max_crawls(n, m, corridors):
    adjacency = {i: [] for i in range(1, 2*n + 1)}
    for i in range(1, n + 1):
        side = [int(v) for v in input().split()]
        if i < n:
            adjacency[2*i - 1] = side
        else:
            for j in range(0, n, n-1):
                nearest = j + ((i & (1 << (n-1))) // 2)
                bottom = [(i+1<<nearest, v) for v in side[j:j+n]]
                top = [(i+1 - nearest << nearest, v) for v in side[nearest:]]
                adjacency[2*i] += bottom
                adjacency[2*i + 1] += top

    q = []
    for k in adjacency.values():
        heappush(q, (k[0], k[1]))

    ans = 0
    while q:
        _, v = heappop(q)
        if v not in adjacency:
            ans += 1
        for i in adjacency:
            if i >= 19 or adjacency[i] <= 0:
                break
            if v <= adjacency[i][0]:  # corridor capacity should disqualify us
                adjacency[i] = -1
    return ans

