                else:
                    actions.append(f'-{tunnel}')
                    break
        else:
            for tunnel in tunnels:
                if wave == 1:
                    actions.append(f'+{tunnel - 1}')
                else:
                    actions.append(f'+{2 * wave - tunnel}')
                    break
        for _ in range(wave):
            actions.append('0')

