import functools

def max_product_of_components(n, edges):
    # Create a graph from the input edges
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)

    @functools.lru_cache(None)
    def dfs(v, component_size=1):
        for adj_v in graph[v]:
            if adj_v not in visited:
                visited.add(adj_v)
                component_size += dfs(adj_v, component_size)
        return component_size

    max_size = 1
    visited = set()
    largest_component = 0
    for v in range(n):
        visited.add(v)
        processed_size = dfs(v, 1)
        if processed_size > largest_component:
            largest_component = processed_size
        max_size = max(max_size, (n - 2 * largest_component + 1) // 2)

    return max_size * (n // max_size)

