        for j in range(i, n, i):
            cs.append((j, i))
            if (i, n) in cs:
                return (bin(n//i) * bin(n%(n//i)))[2:].count('1')
                break

    for group in combinations(cs, n//2):
        if all(math.gcd(a[0], b[0]) > 1 and math.gcd(a[1], b[1]) > 1 for a, b in combinations(group, 2)):
            max_groups += 1
    return max_groups

def main():
    n = int(input())
    print(maximize_groups(n))
    for i in range(int(n**0.5)):
        print(n - 2*i, 2*i+1)

if __name__ == "__main__":
    main()
